// Crusaders Mainframe — turning scanner bytes into one token, or into nothing.
//
// WHAT ARRIVES
// ------------
// A serial barcode module on Serial2 at 9600 8N1. It emits the decoded payload
// followed by \r, \n or \r\n, on its own schedule, whenever somebody presents a
// phone — and it repeats while the phone is held there. 9600 baud over jumper
// wire beside a switching relay coil produces truncated payloads, split lines
// and dropped terminators in normal service, not just in theory.
//
// THE RULES, FROM THE CONTRACT
// ----------------------------
//   * bytes accumulate until CR or LF; CRLF is one terminator, not two
//   * the line is trimmed of leading and trailing whitespace
//   * an empty line is ignored entirely — no decision, no LED, no event
//   * a line longer than the token cap is REFUSED, never truncated, and the
//     rest of that line is discarded
//   * a byte outside the ROSTER'S TOKEN ALPHABET discards the whole line
//
// WHY REFUSE RATHER THAN TRUNCATE
// -------------------------------
// The same rule as roster::Entry's: a token cut short is a DIFFERENT token, and
// a different token can match a different member. Twenty-one characters
// truncated to twenty is not "nearly right", it is somebody else's booking.
//
// WHY A BYTE OUTSIDE THE ALPHABET COSTS THE LINE
// ----------------------------------------------
// Two reasons, and the second is round G4's B1.
//
// It is the signature of the noise this cable actually produces. A framing
// error inserts a byte nobody typed; carrying on with the rest of the line
// would present the server with a token that is neither what was scanned nor
// anything it can recognise, and would spend an API call doing it.
//
// And the set is `roster::isTokenChar` rather than "printable ASCII", because
// printable ASCII includes `"` and `\`. A QR code carries whatever somebody
// printed on it, and the token was interpolated into a JSON body with a bare
// `%s`: `a","method":"code` is seventeen characters and re-wrote `method`;
// `","seq":99999,"x":"` is nineteen and forged an offline batch's sequence
// number, so the server acknowledged — and the board then discarded — every
// genuine door entry queued behind it. The renderers escape now too, but a
// token outside the roster's alphabet can never match anything in the roster
// and can never be a code the server minted, so admitting one was never
// anything but a refusal taken slowly.
//
// AND A DISCARDED LINE IS ANSWERED
// --------------------------------
// Round G4's L1. `feed` returned `None` for a corrupt line, so a member whose
// scan met line noise got no blink, no record and nothing anybody could see —
// while `GateApp::pumpScanner`'s comment had promised them feedback since the
// day it was written. It returns `Corrupt` now; what the caller DOES about it
// is rate-limited there, because a noisy cable produces these by the hundred
// and neither the lamp nor the event ring may be driven by line noise.
//
// No Arduino headers, no heap, no String. Compiles for Xtensa and the host.

#ifndef CRUSADERS_GATELOGIC_SCANASSEMBLER_H
#define CRUSADERS_GATELOGIC_SCANASSEMBLER_H

#include <stddef.h>
#include <stdint.h>

#include "../roster/Roster.h"

namespace gatelogic {

/// CR or LF, and the one place the terminator set is written down.
///
/// The loop's overrun drain has to know where a line ends too — it discards
/// what was buffered and then everything through the NEXT terminator — and two
/// copies of "what ends a line" that could disagree is how the far side of a
/// hole becomes the head of somebody's token. One return statement: the
/// generated sketch compiles at gnu++11.
constexpr bool isLineTerminator(uint8_t byte) {
  return byte == 0x0DU || byte == 0x0AU;
}

/// What one byte produced.
enum class ScanEvent : uint8_t {
  /// Nothing yet, or a line that was discarded without a decision: empty, or
  /// corrupted by a non-printable byte.
  None = 0U,
  /// A complete, printable, trimmed, in-bounds token. Read it with token().
  Token = 1U,
  /// A complete line this board refuses without looking at it: too long for the
  /// token cap. The caller denies it exactly as it denies an unknown token —
  /// the bytes are gone and there is nothing to ask the API about.
  Refused = 2U,
  /// A complete line that was CORRUPTED — a byte outside the roster's token
  /// alphabet, or a UART overrun `markCorrupt()` poisoned it with. Refused for
  /// the same reason and answered the same way; a separate value only so the
  /// caller can rate-limit it, because line noise produces these by the
  /// hundred and an over-long QR code does not.
  Corrupt = 3U,
};

class ScanAssembler {
public:
  /// Feed one received byte.
  ScanEvent feed(uint8_t byte);

  /// The token from the last ScanEvent::Token. NUL-terminated; empty otherwise.
  const char* token() const { return token_; }

  /// Throw away a partial line — on a link-down, or at boot.
  void reset();

  /// The line in flight has a HOLE in it: the UART dropped bytes before they
  /// reached this class.
  ///
  /// Not reset(): reset would leave the REST of the holed line to be read as
  /// the head of the next token, which is the same mistake in a different
  /// place. This marks the line corrupt, so everything up to and including its
  /// next terminator is swallowed with it — exactly what a non-printable byte
  /// does, and for the same reason. A serial overrun is silent and what arrives
  /// afterwards is in order, printable and short: it trims, it fits the token
  /// cap, and it is not what anybody scanned.
  void markCorrupt();

  /// `markCorrupt`, stamped now: the rest of a holed line is still arriving,
  /// and the idle gap is measured from the hole, not from the last clean byte.
  void markCorrupt(uint32_t nowMs) {
    lastByteMs_ = nowMs;
    markCorrupt();
  }

  /// `feed`, remembering when the byte arrived, for `idle` (DG-5).
  ScanEvent feed(uint8_t byte, uint32_t nowMs);

  /// Called on a pass that found the UART EMPTY — never across a blocking call
  /// whose bytes are still waiting to be read. A line that has had no byte for
  /// kScanIdleGapMs is ended: a whole token of at least kIdleTokenMinLen
  /// characters is a scan from a scanner with no CR/LF suffix; an over-long one
  /// is refused as any over-long line is; anything shorter or holed is a stray
  /// byte (a scanner powering up, noise on the line) and is dropped silently so
  /// it cannot spoil the next member's scan.
  ScanEvent idle(uint32_t nowMs);

  /// Some part of a line is held. The board is not idle while one is, so no
  /// self-restart takes the door down under a half-read scan.
  bool partial() const { return len_ > 0U || overflow_ || corrupt_; }

private:
  char line_[roster::kMaxTokenLen + 1U] = {};
  char token_[roster::kMaxTokenLen + 1U] = {};
  /// Characters held in `line_`. Stops at the cap; `overflow_` remembers that
  /// more arrived, which is what makes the refusal a refusal and not a
  /// truncation.
  uint8_t len_ = 0U;
  bool overflow_ = false;
  bool corrupt_ = false;
  uint32_t lastByteMs_ = 0U;
};

/// The gap that ends a line on this hardware (device-api.md §5's
/// `hw_scanner_gap_ms` default). A 12-character code takes 13 ms at 9600 baud.
inline constexpr uint32_t kScanIdleGapMs = 150UL;

/// The shortest line an idle gap ends as a token: the Mega's rule, so both
/// devices treat a suffix-less scanner the same way. No real code is shorter.
inline constexpr uint8_t kIdleTokenMinLen = 8U;

} // namespace gatelogic

#endif // CRUSADERS_GATELOGIC_SCANASSEMBLER_H
